+    export LANG=en_US.UTF-8
+
+    touch /etc/group
+    ${pkgs.busybox}/bin/addgroup postgres
+    ${pkgs.busybox}/bin/adduser -HSD -G postgres postgres
+    mkdir -p /run/postgresql
+    chown -R postgres /run/postgresql
+    mkdir postgres
+    chown -R postgres postgres
+    chmod -R 0700 postgres
+    PGDATA=$PWD/postgres ${pkgs.busybox}/bin/su postgres -p -c ${config.services.postgresql.package}/bin/initdb
+    PGDATA=$PWD/postgres ${pkgs.busybox}/bin/su postgres -p -c ${config.services.postgresql.package}/bin/postgres &
+    sleep 1
+    ${pkgs.busybox}/bin/su postgres -p -c "${config.services.postgresql.package}/bin/psql -c \"CREATE DATABASE fastnetmon;\""
+    ${pkgs.busybox}/bin/su postgres -p -c "${config.services.postgresql.package}/bin/psql -c \"CREATE USER fastnetmon WITH ENCRYPTED PASSWORD 'foobar';\""
+    ${pkgs.busybox}/bin/su postgres -p -c "${config.services.postgresql.package}/bin/psql -c \"GRANT ALL PRIVILEGES ON DATABASE fastnetmon TO fastnetmon;\""
+
+    FERRETDB_POSTGRESQL_URL="postgresql://localhost:5432" FERRETDB_TELEMETRY="disable" ${pkgs.ferretdb}/bin/ferretdb &
+
+    mkdir -p /etc/fastnetmon/keychain
+    cat << EOF > /etc/fastnetmon/fastnetmon.conf
+    ${builtins.toJSON {
+      mongodb_host = "127.0.0.1";
+      mongodb_port = 27017;
+      mongodb_database_name = "fastnetmon";
+      mongodb_username = "fastnetmon";
+      mongodb_auth_mechanism = "PLAIN"; # required for FerretDB
+    }}
+    EOF
+    echo foobar > /etc/fastnetmon/keychain/.mongo_fastnetmon_password
+    ${pkgs.fastnetmon-advanced}/bin/fcli create_configuration
+    ${pkgs.fastnetmon-advanced}/bin/fcli set bgp default
+    ${pkgs.fastnetmon-advanced}/bin/fcli export_configuration backup.tar
