+
+    settings = mkOption {
+      description = mdDoc "Extra configuration options to declaratively load into FastNetMon Advanced";
+      type = settingsFormat.type;
+      default = {};
+    };
+    hostgroups = mkOption {
+      description = mdDoc "Hostgroups to declaratively load into FastNetMon Advanced";
+      type = types.attrsOf settingsFormat.type;
+      default = {};
+    };
+    bgpPeers = mkOption {
+      description = mdDoc "BGP Peers to declaratively load into FastNetMon Advanced";
+      type = types.attrsOf settingsFormat.type;
+      default = {};
+    };
+
+    enableAdvancedTrafficPersistence = mkOption {
+      description = mdDoc "Store historical flow data in clickhouse";
+      type = types.bool;
+      default = false;
+    };
+  };
+
+  config = lib.mkMerge [ (lib.mkIf cfg.enable {
+    services.fastnetmon-advanced.settings.pid_path = "/run/fastnetmon/fastnetmon.pid";
+
+    environment.systemPackages = with pkgs; [
+      fastnetmon-advanced
+    ];
+
+    # FastNetMon Advanced *requires* a MongoDB to store its configuration in
+    # We use PostgreSQL + FerretDB instead of MongoDB because MongoDB is not in the binary cache: SSPL license is not OSI approved thus considered unfree
+    services.postgresql = {
+      enable = true;
+      ensureDatabases = [ "fastnetmon" ];
+      ensureUsers = [
+        {
+          name = "fastnetmon";
+          ensurePermissions = { "DATABASE fastnetmon" = "ALL PRIVILEGES"; };
+        }
+      ];
+    };
+
+    systemd.services.ferretdb = {
+      wantedBy = [ "multi-user.target" ];
+      serviceConfig = {
+        ExecStart = "${pkgs.ferretdb}/bin/ferretdb";
+        DyanmicUser = true;
+      };
+      environment = {
+        FERRETDB_POSTGRESQL_URL = "postgresql://localhost:5432";
+        FERRETDB_LOG_LEVEL = "debug";
+        FERRETDB_TELEMETRY = "disable";
+      };
+    };

